package com.autumnharvestc.server.sync;
import com.autumnharvestc.server.store.UserAccount;
import com.autumnharvestc.server.collaboration.runtime.RuntimeProtocol;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.stereotype.Service;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
@Service @Transactional
public class SyncHistoryService {
    private final JdbcTemplate jdbc;private final ObjectMapper json;private final SyncSourceService sources;private final SyncPolicyService policies;private final SyncStorage accounting;
    public SyncHistoryService(JdbcTemplate jdbc,ObjectMapper json,SyncSourceService sources,SyncPolicyService policies,SyncStorage accounting){this.policies=policies;this.accounting=accounting;this.jdbc=jdbc;this.json=json;this.sources=sources;}
    static ObjectNode seal(ObjectMapper json,String kind,ObjectNode value){value.put("integritySha256",RuntimeProtocol.digestJson(json.createArrayNode().add("apicc-sync-online-"+kind+"-v1").add(value.deepCopy())));return value;}
    static void verify(ObjectMapper json,String kind,JsonNode value){var copy=(ObjectNode)value.deepCopy();String expected=copy.path("integritySha256").asText();copy.remove("integritySha256");if(!RuntimeProtocol.digestJson(json.createArrayNode().add("apicc-sync-online-"+kind+"-v1").add(copy)).equals(expected))throw SyncDtos.conflict("sync_"+kind+"_integrity_mismatch");}
    void save(long ws,long project,JsonNode entry,JsonNode artifacts){String before=artifacts.path("before").path("text").asText(),after=artifacts.path("after").path("text").asText();jdbc.update("INSERT INTO sync_history(workspace_id,project_id,id,source_id,history_json,before_content,after_content,content_bytes) VALUES(?,?,?,?,?,?,?,?)",ws,project,entry.path("id").asText(),entry.path("sourceId").asText(),entry.toString(),before,after,(long)before.getBytes(java.nio.charset.StandardCharsets.UTF_8).length+after.getBytes(java.nio.charset.StandardCharsets.UTF_8).length+entry.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length);jdbc.update("UPDATE sync_sources SET current_history_id=? WHERE workspace_id=? AND project_id=? AND id=?",entry.path("id").asText(),ws,project,entry.path("sourceId").asText());retain(ws,project,entry.path("sourceId").asText(),policies.requireEffective(ws,project).path("policy"));}
    void pin(long ws,long project,String historyId,String owner,long expires){var text=jdbc.queryForObject("SELECT active_owners_json FROM sync_history WHERE workspace_id=? AND project_id=? AND id=?",String.class,ws,project,historyId);var pins=(com.fasterxml.jackson.databind.node.ArrayNode)decode(text);pins.addObject().put("id",owner).put("expiresAtMs",expires);jdbc.update("UPDATE sync_history SET active_owners_json=?,reference_count=reference_count+1 WHERE workspace_id=? AND project_id=? AND id=?",pins.toString(),ws,project,historyId);accounting.changed(ws,project);}
    void requirePin(long ws,long project,String historyId,String owner){var values=jdbc.queryForList("SELECT active_owners_json FROM sync_history WHERE workspace_id=? AND project_id=? AND id=?",String.class,ws,project,historyId);if(values.isEmpty()||!java.util.stream.StreamSupport.stream(decode(values.getFirst()).spliterator(),false).anyMatch(pin->pin.path("id").asText().equals(owner)&&pin.path("expiresAtMs").asLong()>System.currentTimeMillis()))throw SyncDtos.conflict("sync_operation_expired");}
    void unpin(long ws,long project,String historyId,String owner){var rows=jdbc.queryForList("SELECT active_owners_json FROM sync_history WHERE workspace_id=? AND project_id=? AND id=?",String.class,ws,project,historyId);if(rows.isEmpty())return;var pins=json.createArrayNode();decode(rows.getFirst()).forEach(pin->{if(!pin.path("id").asText().equals(owner))pins.add(pin);});jdbc.update("UPDATE sync_history SET active_owners_json=? WHERE workspace_id=? AND project_id=? AND id=?",pins.toString(),ws,project,historyId);retain(ws,project,null,policies.requireEffective(ws,project).path("policy"));}
    /** Caller supplies the actual resolved policy under the existing scope gates. Null admissionSource denotes maintenance. */
    int retain(long ws,long project,String admissionSource,JsonNode policy){
        long cutoff=System.currentTimeMillis()-policy.path("historyRetentionDays").asLong()*86400000L;int maximum=policy.path("historyMaxEntries").asInt();
        var owners=new HashMap<String,Integer>();for(String id:jdbc.queryForList("SELECT current_history_id FROM sync_sources WHERE workspace_id=? AND project_id=? AND current_history_id IS NOT NULL",String.class,ws,project))owners.merge(id,1,Integer::sum);
        for(String response:jdbc.queryForList("SELECT response_json FROM sync_operations WHERE workspace_id=? AND project_id=? AND kind IN ('apply','rollback') AND created_at>=?",String.class,ws,project,new java.sql.Timestamp(cutoff))){var receipt=decode(response);verify(json,"receipt",receipt);owners.merge(receipt.path("historyId").asText(),1,Integer::sum);}
        var rows=jdbc.query("SELECT id,source_id,history_json,active_owners_json,created_at FROM sync_history WHERE workspace_id=? AND project_id=? ORDER BY created_at ASC,id ASC",(r,n)->new Object[]{r.getString(1),r.getString(2),decode(r.getString(3)),decode(r.getString(4)),r.getTimestamp(5).getTime()},ws,project);var retainedBySource=new HashMap<String,Integer>();for(var row:rows)retainedBySource.merge((String)row[1],1,Integer::sum);int removed=0;
        for(var row:rows){String id=(String)row[0],source=(String)row[1];var pins=json.createArrayNode();((JsonNode)row[3]).forEach(pin->{if(pin.path("expiresAtMs").asLong()>System.currentTimeMillis())pins.add(pin);});int count=owners.getOrDefault(id,0)+pins.size();jdbc.update("UPDATE sync_history SET reference_count=?,active_owners_json=? WHERE workspace_id=? AND project_id=? AND id=?",count,pins.toString(),ws,project,id);
            if(count==0&&((Long)row[4]<cutoff||retainedBySource.get(source)>maximum)){jdbc.update("DELETE FROM sync_history WHERE workspace_id=? AND project_id=? AND id=?",ws,project,id);retainedBySource.compute(source,(key,value)->value-1);removed++;}
        }
        jdbc.update("UPDATE sync_candidates SET reference_count=CASE WHEN expires_at>CURRENT_TIMESTAMP THEN 1 ELSE 0 END WHERE workspace_id=? AND project_id=?",ws,project);
        removed+=jdbc.update("DELETE FROM sync_candidates WHERE workspace_id=? AND project_id=? AND reference_count=0",ws,project);accounting.changed(ws,project);
        if(admissionSource!=null&&retainedBySource.getOrDefault(admissionSource,0)>maximum)throw SyncDtos.conflict("sync_history_limit");return removed;
    }
    record Stored(JsonNode entry,JsonNode before,JsonNode after) {}
    Stored stored(long ws,long project,String id){return jdbc.query("SELECT history_json,before_content,after_content FROM sync_history WHERE workspace_id=? AND project_id=? AND id=?",(r,n)->{var entry=decode(r.getString(1));verify(json,"history",entry);return new Stored(entry,content(r.getString(2),entry.path("rollback").path("beforeContent")),content(r.getString(3),entry.path("rollback").path("afterContent")));},ws,project,id).stream().findFirst().orElseThrow(()->SyncRepo.missing("sync_history_not_found"));}
    private JsonNode content(String text,JsonNode reference){if(!com.autumnharvestc.server.core.Hashes.sha256HexUtf8(text).equals(reference.path("digest").asText())||text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length!=reference.path("bytes").asLong())throw SyncDtos.conflict("SYNC_ROLLBACK_CONTENT_MISMATCH");return decode(text);}
    public JsonNode list(UserAccount actor,String ws,String project){sources.requireRead(actor,ws,project);return json.valueToTree(jdbc.query("SELECT history_json FROM sync_history WHERE workspace_id=? AND project_id=? ORDER BY created_at DESC,id DESC",(r,n)->decode(r.getString(1)),Long.parseLong(ws),Long.parseLong(project)));}
    JsonNode decode(String text){try{return json.readTree(text);}catch(Exception e){throw new IllegalStateException("Invalid stored synchronization history",e);}}
}
